"""Spec for X14_UISS_Batch_ASNSubmit.xlsx (UISS-Batch): the batch behind [Submit ASN] of ASN Crossdock Creation (X8).
The screen hands the ASN (rows of TB_R_INSTRUCTION) to this batch with a Submit ID; the result is written to the existing log."""
import json, sys
from asn_common import ASND, ASND_TABLE, ASNH, ASNH_TABLE, DRAFT, DRAFT_COLS, DRAFT_TABLE, NC, PRA_MAP, header, revisions

LOG = 'Log (existing)'

spec = {
 "doc_type": "batch",
 "header": header("X14", "Batch", "ASN Submit", '15-Oct-26'),
 "revisions": revisions('15-Oct-26'),
 "general": {
  "objective": [
   "To save the ASN of ASN Crossdock Creation (X8) when the user confirms [Submit ASN]: the mapping in TB_R_INSTRUCTION is written into the existing ASN tables TB_R_DAILY_ORDER_MANIFEST (status Created) and TB_R_DAILY_ORDER_PART.",
   "The screen does not wait for the result: it shows the Submit ID and the batch writes its messages to the existing log (Log Monitoring). In case any error occurs, nothing is saved (all-or-nothing)."],
  "operation_flow": {"flow": {"direction": "TB", "nodes": [
     {"id": "a", "label": "[Submit ASN] Yes on X8: Submit ID", "type": "event"},
     {"id": "b", "label": "Take ASN No / Case No (existing numbering, last sequence)", "type": "process"},
     {"id": "c", "label": "Insert Daily Order Manifest / Part, update TB_R_INSTRUCTION", "type": "process"},
     {"id": "d", "label": "Commit / roll back, write log", "type": "process"}],
    "edges": [{"from": "a", "to": "b"}, {"from": "b", "to": "c"}, {"from": "c", "to": "d"}]}},
  "inputs": [
   {"name": "Submit ID", "type": "Parameter", "description": "Generated by X8 at [Submit ASN] Yes (existing ASN submit process); key of the log record"},
   {"name": DRAFT, "type": "DB", "description": "Mapping rows inserted by [Create ASN] (cases, lines, PO, Delivery Date, Rit, Route) of one Supplier Code + Plant"}],
  "outputs": [
   {"name": ASNH, "type": "DB", "description": "if successful: one ASN (existing table), status Created"},
   {"name": ASND, "type": "DB", "description": "if successful: one row per case (existing table)"},
   {"name": DRAFT, "type": "DB", "description": "if successful: ASN_NO and CASE_NO written back; on error the rows are deleted (mapping released)"},
   {"name": LOG, "type": "DB", "description": "Start, result and end messages with the Submit ID (existing log format)"}],
  "extra_tables": [
   {"title": "Parameters", "columns": [{"title": "Name", "width": 14}, {"title": "Description", "width": 34}],
    "rows": [["Submit ID", "Generated by X8; the submit process follows the existing ASN"], ["User ID", "Login user of X8"]]},
   {"title": "Execution Schedule", "columns": [{"title": "Item", "width": 12}, {"title": "Description", "width": 36}],
    "rows": [["Trigger", "On demand: [Submit ASN] Yes on ASN Crossdock Creation (X8). No scheduler."]]}]
 },
 "func_flow": {
  "flow": {"direction": "TB", "nodes": [
     {"id": "p1", "label": "Start (Submit ID)", "type": "process", "step": 1},
     {"id": "dr", "label": DRAFT, "type": "db", "lane": "input"},
     {"id": "p2", "label": "Take ASN No / Case No", "type": "process", "step": 2},
     {"id": "p3", "label": "Insert header and cases", "type": "process", "step": 3},
     {"id": "h", "label": ASNH + " / " + ASND, "type": "db", "lane": "output"},
     {"id": "p4", "label": "Commit or roll back, log", "type": "process", "step": 4},
     {"id": "log", "label": LOG, "type": "db", "lane": "output"}],
   "edges": [{"from": "p1", "to": "p2"}, {"from": "dr", "to": "p2"}, {"from": "p2", "to": "p3"}, {"from": "p3", "to": "h"}, {"from": "p3", "to": "p4"}, {"from": "p4", "to": "log"}]},
  "steps": [
   "X8 generates the Submit ID, writes the start message to the log (LOG1) and starts this batch. The screen returns to the delivery plan and shows the Submit ID.",
   f"Read the rows of the Submit ID from {DRAFT} (one Supplier Code + Plant). Take the ASN No from the existing numbering and auto generate one Case No per case by checking the last sequence (existing last sequence table; format as existing).",
   f"Insert {ASNH} (status Created) and {ASND} (existing tables, refer Data Edit Mapping); write ASN_NO / CASE_NO back to {DRAFT}.",
   f"No error: commit, write the result (LOG2) and end (LOG3) messages. Error: roll back, release the mapping (delete the rows from {DRAFT}, PO_MAPPED_FLAG back to 'N', MAPPED_QTY of {PRA_MAP} reduced again), write the error (LOG4). Exit."]
 },
 "data_map": {"blocks": [
  {"source": DRAFT, "destination": {"table": ASNH, "operation": "Insert", "description": "One ASN per Submit ID (existing table; physical columns as existing)"},
   "mappings": [
     {"dest_field": "MANIFEST_NO / ASN_NO", "description": "Existing ASN numbering"},
     {"source_field": "SUPPLIER_CD", "dest_field": "SUPPLIER_CD"}, {"source_field": "SUPPLIER_PLANT", "dest_field": "SUPPLIER_PLANT"},
     {"source_field": "DELIVERY_DT", "dest_field": "DELIVERY_DT"}, {"source_field": "RIT_CYCLE / ROUTE", "dest_field": "RIT / ROUTE"},
     {"dest_field": "TOTAL_CASE / TOTAL_QTY", "description": "Number of CASE_SEQ / sum of QTY"}, {"dest_field": "STATUS", "description": "Created"},
     {"dest_field": "CREATED_BY / CREATED_DT", "description": "User ID, server system date-time"}]},
  {"source": DRAFT, "destination": {"table": ASND, "operation": "Insert", "description": "One row per case (existing table; physical columns as existing)"},
   "mappings": [{"dest_field": "MANIFEST_NO / ASN_NO", "description": "ASN No of the manifest"},
                {"dest_field": "CASE_NO", "description": "Auto generated per CASE_SEQ by checking the last sequence (existing table, existing format)"},
                {"source_field": "PART_NO", "dest_field": "PART_NO"}, {"source_field": "DESTINATION_CD", "dest_field": "DESTINATION_CD"},
                {"dest_field": "QTY", "description": "Sum of QTY of the case"}, {"source_field": "PO_NO / MANIFEST_ITEM_NO", "dest_field": "PO_NO / MANIFEST_ITEM_NO"},
                {"dest_field": "CREATED_BY / CREATED_DT", "description": "User ID, server system date-time"}]},
  {"source": "Result of the inserts", "destination": {"table": DRAFT, "operation": "Update", "description": "Every row of the Submit ID",
                                                    "keys": [{"field": "INSTRUCTION_ID", "value": "Rows of the Submit ID"}]},
   "mappings": [{"dest_field": "ASN_NO", "description": "ASN No of the manifest"}, {"dest_field": "CASE_NO", "description": "Case No of the CASE_SEQ"},
                {"dest_field": "CHANGED_BY", "description": "User ID"}, {"dest_field": "CHANGED_DT", "description": "Server system date-time"}] +
               [{"dest_field": c[0], "description": NC} for c in DRAFT_COLS if c[0] not in ("ASN_NO", "CASE_NO", "CHANGED_BY", "CHANGED_DT")]},
  {"source": "Result of this run", "destination": {"table": LOG, "operation": "Insert", "description": "Messages of the Submit ID (existing log columns)"},
   "mappings": [{"dest_field": "Process / Submit ID", "description": "Submit ID"}, {"dest_field": "Function ID", "description": "'X14'"},
                {"dest_field": "Status", "description": "PROCESSING / SUCCESS / ERROR"}, {"dest_field": "Message ID / Message", "description": "LOG1 - LOG4"},
                {"dest_field": "User / Date-time", "description": "User ID, server system date-time"}]}]},
 "func_desc_layout": "full",
 "func_desc": [
  {"type": "bullets", "marker": "-", "level": 0, "items": [
    "Submit ASN runs as a batch so the screen does not wait; the user sees the Submit ID and checks the result in Log Monitoring. No success popup is shown on X8.",
    "The log follows the existing Supplier System log (same table and columns); the Submit ID is the key to find the run.",
    "All-or-nothing: on error nothing is saved and the mapping made by [Create ASN] is released (rows deleted from TB_R_INSTRUCTION), so the units can be selected again.",
    "The ASN is saved in the existing tables TB_R_DAILY_ORDER_MANIFEST / TB_R_DAILY_ORDER_PART; the case number is auto generated by checking the last sequence kept in the existing last sequence table (format as existing, not detailed here).",
    "The submit process (Submit ID, batch call, log) follows the existing ASN submit of Supplier System."]}],
 "logging_messages": [
  {"event": "Batch start", "cause": "[Submit ASN] Yes", "type": "Info", "msg_id": "LOG1", "message": "ASN submit started. Submit ID <SUBMIT_ID>, <n> cases.", "action": {"system": "Write the log.", "user": "-"}},
  {"event": "Save", "cause": "ASN saved", "type": "Info", "msg_id": "LOG2", "message": "<ASN_NO> submitted with status Created. <n> cases are saved. Delivery <DELIVERY_DT> · <RIT>. The ASN is shown in ASN Inquiry.", "action": {"system": "Write the log.", "user": "-"}},
  {"event": "Batch end", "cause": "Batch finishes", "type": "Info", "msg_id": "LOG3", "message": "ASN submit ended. Status <STATUS>.", "action": {"system": "Write the log.", "user": "-"}},
  {"event": "Error", "cause": "Numbering or insert fails / any system error", "type": "Error", "msg_id": "LOG4", "message": "Failed to submit ASN, Submit ID <SUBMIT_ID>: <ERROR_DETAIL>.", "action": {"system": "Roll back; release the mapping. STATUS = ERROR.", "user": "Create the ASN again; contact PIC if it persists."}}],
 "appendix_layout": "full",
 "appendix": [],
 "tables": [DRAFT_TABLE, ASNH_TABLE, ASND_TABLE]
}
json.dump(spec, open(sys.argv[1], 'w'), indent=1)
